module tb;

//declare:
// 1) Inputs & Inouts driven by TB
logic clk;
logic reset;
logic CE;
logic [7:0] input_byte;

// 2) Outputs & Inouts observed from DUT/REF
wire [7:0] Out_byte_dut;
wire [7:0] Out_byte_ref;
wire CEO_dut;
wire CEO_ref;
wire Valid_out_dut;
wire Valid_out_ref;

// 2.1) Output queues and events
logic [7:0] Out_byte_ref_q[$];
logic [7:0] Out_byte_ref_pop;
logic [7:0] Out_byte_dut_q[$];
logic [7:0] Out_byte_dut_pop;
event Out_byte_ref_event;
int errortime_Out_byte_dut_q[$];
int errortime_Out_byte_dut_pop;
logic CEO_ref_q[$];
logic CEO_ref_pop;
logic CEO_dut_q[$];
logic CEO_dut_pop;
event CEO_ref_event;
int errortime_CEO_dut_q[$];
int errortime_CEO_dut_pop;
logic Valid_out_ref_q[$];
logic Valid_out_ref_pop;
logic Valid_out_dut_q[$];
logic Valid_out_dut_pop;
event Valid_out_ref_event;
int errortime_Valid_out_dut_q[$];
int errortime_Valid_out_dut_pop;

// 2.2) signal for tb
int test_errors;

// 2.3) signal for verilogcoder
typedef struct packed {
    int errors;
    int errortime;
    int clocks;

    int errors_Out_byte;
    int errortime_Out_byte;
    int errors_CEO;
    int errortime_CEO;
    int errors_Valid_out;
    int errortime_Valid_out;
    int samples;

} stats;

stats stats1;

//link:
// 3) Instances
TopModule dut (
  .clk(clk),
  .reset(reset),
  .CE(CE),
  .input_byte(input_byte),
  .Out_byte(Out_byte_dut),
  .CEO(CEO_dut),
  .Valid_out(Valid_out_dut)
);

RefModule ref_mdl (
  .clk(clk),
  .reset(reset),
  .CE(CE),
  .input_byte(input_byte),
  .Out_byte(Out_byte_ref),
  .CEO(CEO_ref),
  .Valid_out(Valid_out_ref)
);

task automatic monitor_dut;
  bit prev_valid;
  prev_valid = Valid_out_dut;
  forever begin
    @(posedge clk);
    if (Valid_out_dut && !prev_valid) begin
      int i;
      for (i = 0; i < 188; i++) begin
        while (!CEO_dut) @(posedge clk);
        @(posedge clk);
        Out_byte_dut_q.push_back(Out_byte_dut);
        errortime_Out_byte_dut_q.push_back($time);
      end
    end
    prev_valid = Valid_out_dut;
  end
endtask

task automatic monitor_ref;
  bit prev_valid;
  prev_valid = Valid_out_ref;
  forever begin
    @(posedge clk);
    if (Valid_out_ref && !prev_valid) begin
      int i;
      for (i = 0; i < 188; i++) begin
        while (!CEO_ref) @(posedge clk);
        @(posedge clk);
        Out_byte_ref_q.push_back(Out_byte_ref);
        -> Out_byte_ref_event;
        stats1.samples++;
      end
    end
    prev_valid = Valid_out_ref;
  end
endtask

// Auto-generated checker tasks (inline)
// Notes:
//  - Assumes external declarations of queues/events/vars: *_ref_q, *_dut_q, *_ref_event, *_ref_pop, *_dut_pop, errors.
//  - One checker task per data base name.


// === Auto-generated checker for Out_byte ===
task checker_Out_byte;
    realtime t1, t2, ref_time;
    t1 = $realtime;
    //$display("@%0d,waiting Out_byte_ref_event", $time);
    @(Out_byte_ref_event);
    t2 = $realtime;
    ref_time = t2 - t1;
    //$display("@%0d,wait Out_byte_ref_event done", $time);
    if (Out_byte_dut_q.size() > 0) begin
        Out_byte_ref_pop = Out_byte_ref_q.pop_front();
        Out_byte_dut_pop = Out_byte_dut_q.pop_front();
        errortime_Out_byte_dut_pop = errortime_Out_byte_dut_q.pop_front();
        if (Out_byte_ref_pop == Out_byte_dut_pop) begin
            //$display("[check Out_byte passed] @time:%0t dut=%0h, ref=%0h ",
            //         $time, Out_byte_dut_pop, Out_byte_ref_pop);
        end
        else begin
            if (stats1.errors_Out_byte == 0) begin
                stats1.errortime_Out_byte = errortime_Out_byte_dut_pop;
                if (stats1.errors == 0) stats1.errortime = errortime_Out_byte_dut_pop;
            end
            stats1.errors_Out_byte++;
            stats1.errors++;
            test_errors++;
            $display("[check Out_byte FAILED] @time:%0t dut=%0h, ref=%0h ",
                     $time, Out_byte_dut_pop, Out_byte_ref_pop);
        end
    end
    else begin
        fork
            begin
                wait (Out_byte_dut_q.size() > 0);
                Out_byte_ref_pop = Out_byte_ref_q.pop_front();
                Out_byte_dut_pop = Out_byte_dut_q.pop_front();
                errortime_Out_byte_dut_pop = errortime_Out_byte_dut_q.pop_front();
                if (Out_byte_ref_pop == Out_byte_dut_pop) begin
                    //$display("[check Out_byte passed] @time:%0t dut=%0h, ref=%0h ",
                    //         $time, Out_byte_dut_pop, Out_byte_ref_pop);
                end
                else begin
                    if (stats1.errors_Out_byte == 0) begin
                        stats1.errortime_Out_byte = errortime_Out_byte_dut_pop;
                        if (stats1.errors == 0) stats1.errortime = errortime_Out_byte_dut_pop;
                    end
                    stats1.errors_Out_byte++;
                    stats1.errors++;
                    test_errors++;
                    $display("[check Out_byte FAILED] @time:%0t dut=%0h, ref=%0h ",
                             $time, Out_byte_dut_pop, Out_byte_ref_pop);
                end
            end
            begin
                #(ref_time);
                test_errors++;
                $display("[check output protocol FAILED] @time:%0d dut=%0h, ref=%0h ",
                         $time, 0, 1);
                $finish;
            end
        join_any
        disable fork;
    end
endtask

task drive_rst;
  reset = 1'b1;
  CE = 1'b0;
  input_byte = 8'd0;
  repeat (6) @(posedge clk);
  reset = 1'b0;
  repeat (2) @(posedge clk);
endtask

task drive_clk();
  clk = 1'b0;
  forever begin
    #5 clk = ~clk;
  end
endtask

