	  $dumpvars(0, tb);
  end  

  // Monitor both DUT and REF simultaneously
  initial begin
     fork
        monitor_dut;
        monitor_ref;
     join
  end

  // Watchdog for timeout protection
  initial begin
     repeat(1000000)
         @(posedge clk);
     $display("ERROR, watchdog fail");
     $finish();
  end
  always @(posedge clk, negedge clk) begin
     stats1.clocks++;
  end
  // Statistics summary (verilogcoder)
  final begin
    if (stats1.errors_Out_byte)
      $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "Out_byte", stats1.errors_Out_byte, stats1.errortime_Out_byte);
    else
      $display("Hint: Output Out_byte has no mismatches.");
    if (stats1.errors_CEO)
      $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "CEO", stats1.errors_CEO, stats1.errortime_CEO);
    else
      $display("Hint: Output CEO has no mismatches.");
    if (stats1.errors_Valid_out)
      $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "Valid_out", stats1.errors_Valid_out, stats1.errortime_Valid_out);
    else
      $display("Hint: Output Valid_out has no mismatches.");

    $display("Hint: Total mismatched samples is %1d out of %1d samples\n", stats1.errors, stats1.samples);
    $display("Simulation finished at %0d ps", $time);
    $display("Mismatches: %1d in %1d samples", stats1.errors, stats1.samples);
  end


